package com.kaymlyn.planeteater.simulation.infrastructure;

import com.kaymlyn.planeteater.simulation.celestial.CelestialBody;
import com.kaymlyn.planeteater.simulation.resources.Composition;
import com.kaymlyn.planeteater.simulation.celestial.OrbitalSystem;
import com.kaymlyn.planeteater.simulation.resources.Material;
import com.kaymlyn.planeteater.simulation.physics.Vector3D;
import lombok.Getter;

import java.util.Map;

/**
 * Represents the player's orbital platform/base of operations
 * This is the home base where resources are stored and equipment is built
 * 
 * Generated by Claude (Sonnet 4.5)
 */
@Getter
public class OrbitalPlatform {
    private final String id;
    private Vector3D position; // Position in the system
    private Vector3D velocity; // Orbital velocity
    private final Composition inventory; // Stored resources
    private final double orbitRadius; // Distance from star
    private OrbitalSystem system; // Reference to the Orbital System in which it resides
    
    public OrbitalPlatform(String id, double orbitRadius, OrbitalSystem system) {
        this.id = id;
        this.orbitRadius = orbitRadius;
        this.inventory = new Composition();
        this.position = new Vector3D(orbitRadius, 0, 0);
        this.velocity = new Vector3D(0, system.getCentralStar().circularOrbitVelocity(this.orbitRadius), 0);

        this.system = system;
    }
    
    /**
     * Update platform position (follows simple circular orbit)
     */
    public void update(double dt) {
        // For now, maintain circular orbit
        // In the future, could be affected by launches/docking
        double angularVelocity = velocity.magnitude() / orbitRadius;
        double angle = Math.atan2(position.getY(), position.getX());
        angle += angularVelocity * dt;

        double x = orbitRadius * Math.cos(angle);
        double y = orbitRadius * Math.sin(angle);
        position = new Vector3D(x, y, 0);
        
        double vx = -velocity.magnitude() * Math.sin(angle);
        double vy = velocity.magnitude() * Math.cos(angle);
        velocity = new Vector3D(vx, vy, 0);

        // above is the target to maintain,
        // to find stabilization energy:
        // recalculate based on current mass of platform and use the differential to indicate fuel impulse required
    }
    
    /**
     * Add resources to the platform's inventory
     */
    public void addResource(Material material, double mass) {
        inventory.addMaterialAsVolume(material, mass);
    }
    
    /**
     * Remove resources from inventory
     * Returns actual amount removed (amount may be less if insufficient)
     */
    public double removeResource(Material material, double mass) {
        return inventory.removeMaterial(material, mass);
    }
    
    /**
     * Check if platform has sufficient resources
     */
    public boolean hasResource(Material material, double mass) {
        return inventory.getMass(material) >= mass;
    }
    
    /**
     * Get amount of a specific resource in inventory
     */
    public double getResourceAmount(Material material) {
        return inventory.getMass(material);
    }
    
    /**
     * Calculate total inventory mass
     */
    public double getTotalInventoryMass() {
        return inventory.getTotalMass();
    }
    
    /**
     * Calculate distance to a celestial body
     */
    public double distanceTo(CelestialBody body) {
        return position.distanceTo(body.getPosition());
    }
    
    /**
     * Calculate distance to another platform or entity
     */
    public double distanceTo(Vector3D otherPosition) {
        return position.distanceTo(otherPosition);
    }
    
    @Override
    public String toString() {
        return String.format("OrbitalPlatform[id=%s, orbit=%.3e m, inventory=%.3e kg]",
            id, orbitRadius, getTotalInventoryMass());
    }
    
    /**
     * Get a detailed inventory report
     */
    public String getInventoryReport() {
        StringBuilder sb = new StringBuilder();
        sb.append("=== Platform Inventory ===\n");
        sb.append(String.format("Total Mass: %.3e kg\n", getTotalInventoryMass()));
        sb.append("\nResources:\n");
        
        for (Map.Entry<Material, Double> entry : inventory.getMaterials().entrySet()) {
            Material mat = entry.getKey();
            double mass = entry.getValue();
            sb.append(String.format("  %s (%s): %.3e kg\n", 
                mat.name(), mat.getSymbol(), mass));
        }
        
        return sb.toString();
    }
}